"use strict";(globalThis.webpackChunkp_vs_np_docs=globalThis.webpackChunkp_vs_np_docs||[]).push([[7506],{70365(e){e.exports=JSON.parse('{"tag":{"label":"cryptography","permalink":"/azeon/p-vs-np/tags/cryptography","allTagsPath":"/azeon/p-vs-np/tags","count":4,"items":[{"id":"failed-proofs/cryptography-vs-natural-proofs","title":"Cryptography vs. Natural Proofs","description":"Secure encryption needs functions that look random but aren\'t. If such functions exist, they hide their own simplicity so well that the natural way of proving hardness can\'t see it. The thing we want to prove protects itself.","permalink":"/azeon/p-vs-np/failed-proofs/cryptography-vs-natural-proofs"},{"id":"real-world-impact/hash-functions-and-passwords","title":"Hash Functions & Passwords","description":"A good website never knows your password. It stores a fingerprint that\'s easy to compute and believed to be infeasible to reverse. Here\'s how that works, and why the protection isn\'t NP-Hardness, even though it does depend on P \u2260 NP.","permalink":"/azeon/p-vs-np/real-world-impact/hash-functions-and-passwords"},{"id":"real-world-impact/modern-cryptography-rsa","title":"Modern Cryptography (RSA)","description":"How RSA locks a message with a number anyone can see, and why only the person who knows its two prime factors can unlock it. Plus an honest correction: RSA needs much more than P \u2260 NP to be safe.","permalink":"/azeon/p-vs-np/real-world-impact/modern-cryptography-rsa"},{"id":"failed-proofs/the-natural-proofs-barrier","title":"The Natural Proofs Barrier","description":"Razborov and Rudich noticed that every circuit lower bound proof of their time had the same simple shape. Then they proved that, if strong cryptography exists, no proof of that shape can ever separate P from NP.","permalink":"/azeon/p-vs-np/failed-proofs/the-natural-proofs-barrier"}],"unlisted":false}}')}}]);